if not (isinstance(target, int) and isinstance(min_base, int)):
    # wrong types
    return (False, None)
if target < 1 or min_base < 2:
    # domain constraints
    return (False, None)

# Helper: number of distinct prime factors ω(n)
def omega(n):
    cnt = 0
    d = 2
    nn = n
    while d * d <= nn:
        if nn % d == 0:
            cnt += 1
            while nn % d == 0:
                nn //= d
        d += 1 if d == 2 else 2  # small improvement: after 2, test only odd
    if nn > 1:
        cnt += 1
    return cnt

# Helper: primorial of first K primes
def primorial_k(K):
    # Generate first K primes via a simple sieve up to a safe bound
    # For K up to ~10, a small sieve suffices
    # We'll just use a growing trial division approach for simplicity
    primes = []
    candidate = 2
    while len(primes) < K:
        is_p = True
        for q in primes:
            if q * q > candidate:
                break
            if candidate % q == 0:
                is_p = False
                break
        if is_p:
            primes.append(candidate)
        candidate += 1
    m = 1
    for p in primes:
        m *= p
    return m

# Compute minimal K such that 2^K - 1 > target
K = 1
while (1 << K) - 1 <= target:
    K += 1
# Enforce harder-than-seed difficulty: K should be at least 4
if K < 4:
    # Our generator is supposed to yield K >= 4; reject otherwise
    return (False, None)

m = primorial_k(K)
answer_b = m + 1

# If the lower bound min_base exceeds our constructive minimal answer, we would need to search upward
# The generator ensures min_base <= answer_b; enforce this here.
if min_base > answer_b:
    # Not supported by our construction; would require scanning for ω(n) >= K beyond primorial(K)
    return (False, None)

# Validate that answer_b indeed yields count > target using the formula count = 2^{ω(b-1)} - 1
w = omega(answer_b - 1)
count = (1 << w) - 1
if count <= target:
    # Should not happen if construction is correct
    return (False, None)

# Validate minimality logically: for any b < answer_b, b-1 < m, so ω(b-1) <= K-1
# Therefore the maximum possible count below answer_b is 2^{K-1} - 1, which must be <= target.
if (1 << (K - 1)) - 1 > target:
    # If this fails, the instance does not ensure minimality
    return (False, None)

return (True, answer_b)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

